SELECT * FROM t_audit_log
WHERE 1=1

    AND user_id = #{userId}


    AND action = #{action}

ORDER BY created_at DESC
LIMIT #{limit} OFFSET #{offset}

SELECT * FROM t_audit_log
WHERE 1=1

    AND user_id IN (SELECT id FROM t_user WHERE username = #{username})


    AND action = #{action}


    AND resource = #{resource}

ORDER BY created_at DESC
LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*) FROM t_audit_log
WHERE 1=1

    AND user_id IN (SELECT id FROM t_user WHERE username = #{username})


    AND action = #{action}


    AND resource = #{resource}
